ALTER TABLE public.organizations ADD COLUMN location_id uuid REFERENCES public.locations(id), ADD COLUMN status text NOT NULL DEFAULT 'active', ADD COLUMN visibility text NOT NULL DEFAULT 'public', ADD COLUMN reputation integer NOT NULL DEFAULT 0, ADD COLUMN influence integer NOT NULL DEFAULT 0;
ALTER TABLE public.memberships ADD COLUMN status text NOT NULL DEFAULT 'active' CHECK(status IN('active','suspended','former')), ADD COLUMN left_at timestamptz, ADD COLUMN progress integer NOT NULL DEFAULT 0;
CREATE TABLE public.membership_history(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),character_id uuid NOT NULL REFERENCES public.characters(id) ON DELETE CASCADE,organization_id uuid NOT NULL REFERENCES public.organizations(id),action text NOT NULL CHECK(action IN('joined','left')),occurred_at timestamptz NOT NULL);
GRANT SELECT ON public.membership_history TO authenticated; GRANT ALL ON public.membership_history TO service_role; ALTER TABLE public.membership_history ENABLE ROW LEVEL SECURITY; CREATE POLICY "own membership history" ON public.membership_history FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.characters c WHERE c.id=character_id AND c.user_id=auth.uid()));
CREATE TABLE public.social_npcs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),first_name text NOT NULL,last_name text NOT NULL,age integer NOT NULL CHECK(age>=16),city_id text NOT NULL REFERENCES public.cities(id),district_id text NOT NULL REFERENCES public.districts(id),location_id uuid NOT NULL REFERENCES public.locations(id),profession text NOT NULL,description text NOT NULL,traits text[] NOT NULL DEFAULT '{}',appearance jsonb NOT NULL DEFAULT '{}',organization_id uuid REFERENCES public.organizations(id));
GRANT SELECT ON public.social_npcs TO authenticated; GRANT ALL ON public.social_npcs TO service_role; ALTER TABLE public.social_npcs ENABLE ROW LEVEL SECURITY; CREATE POLICY "fictional people read" ON public.social_npcs FOR SELECT TO authenticated USING(true);
CREATE TABLE public.social_stats(character_id uuid PRIMARY KEY REFERENCES public.characters(id) ON DELETE CASCADE,reputation integer NOT NULL DEFAULT 0 CHECK(reputation>=0),influence integer NOT NULL DEFAULT 0 CHECK(influence>=0));
GRANT SELECT ON public.social_stats TO authenticated; GRANT ALL ON public.social_stats TO service_role; ALTER TABLE public.social_stats ENABLE ROW LEVEL SECURITY; CREATE POLICY "own social stats" ON public.social_stats FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.characters c WHERE c.id=character_id AND c.user_id=auth.uid()));
CREATE TABLE public.social_relations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),character_id uuid NOT NULL REFERENCES public.characters(id) ON DELETE CASCADE,npc_id uuid NOT NULL REFERENCES public.social_npcs(id),score integer NOT NULL DEFAULT 0 CHECK(score BETWEEN 0 AND 100),status text NOT NULL DEFAULT 'active',met_at timestamptz NOT NULL,last_interaction timestamptz,UNIQUE(character_id,npc_id));
GRANT SELECT ON public.social_relations TO authenticated; GRANT ALL ON public.social_relations TO service_role; ALTER TABLE public.social_relations ENABLE ROW LEVEL SECURITY; CREATE POLICY "own relations" ON public.social_relations FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.characters c WHERE c.id=character_id AND c.user_id=auth.uid()));
CREATE TABLE public.social_rules(id text PRIMARY KEY,title text NOT NULL,relation_gain integer NOT NULL DEFAULT 0,min_score integer NOT NULL DEFAULT 0,energy_cost integer NOT NULL DEFAULT 0,cooldown_minutes integer NOT NULL DEFAULT 30,reputation_gain integer NOT NULL DEFAULT 0,influence_gain integer NOT NULL DEFAULT 0);
GRANT SELECT ON public.social_rules TO authenticated; GRANT ALL ON public.social_rules TO service_role; ALTER TABLE public.social_rules ENABLE ROW LEVEL SECURITY; CREATE POLICY "social rules read" ON public.social_rules FOR SELECT TO authenticated USING(true);
CREATE TABLE public.social_interactions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),character_id uuid NOT NULL REFERENCES public.characters(id) ON DELETE CASCADE,npc_id uuid NOT NULL REFERENCES public.social_npcs(id),action_id text NOT NULL REFERENCES public.social_rules(id),relation_gain integer NOT NULL,occurred_at timestamptz NOT NULL);
GRANT SELECT ON public.social_interactions TO authenticated; GRANT ALL ON public.social_interactions TO service_role; ALTER TABLE public.social_interactions ENABLE ROW LEVEL SECURITY; CREATE POLICY "own interaction history" ON public.social_interactions FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.characters c WHERE c.id=character_id AND c.user_id=auth.uid()));
CREATE TABLE public.organization_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES public.organizations(id),title text NOT NULL,description text NOT NULL,location_id uuid NOT NULL REFERENCES public.locations(id),start_hour integer NOT NULL DEFAULT 18 CHECK(start_hour BETWEEN 0 AND 23),duration_minutes integer NOT NULL DEFAULT 45 CHECK(duration_minutes>0),energy_cost integer NOT NULL DEFAULT 10,relation_gain integer NOT NULL DEFAULT 5,reputation_gain integer NOT NULL DEFAULT 6,influence_gain integer NOT NULL DEFAULT 2,status text NOT NULL DEFAULT 'active');
GRANT SELECT ON public.organization_events TO authenticated; GRANT ALL ON public.organization_events TO service_role; ALTER TABLE public.organization_events ENABLE ROW LEVEL SECURITY; CREATE POLICY "organization events read" ON public.organization_events FOR SELECT TO authenticated USING(true);
ALTER TABLE public.activities ADD COLUMN organization_event_id uuid REFERENCES public.organization_events(id), ADD COLUMN social_npc_id uuid REFERENCES public.social_npcs(id), ADD COLUMN social_reputation_gain integer NOT NULL DEFAULT 0, ADD COLUMN social_influence_gain integer NOT NULL DEFAULT 0, ADD COLUMN social_relation_gain integer NOT NULL DEFAULT 0;
CREATE TABLE public.social_participations(activity_id uuid PRIMARY KEY REFERENCES public.activities(id) ON DELETE CASCADE,character_id uuid NOT NULL REFERENCES public.characters(id) ON DELETE CASCADE,event_id uuid REFERENCES public.organization_events(id),npc_id uuid REFERENCES public.social_npcs(id),status text NOT NULL DEFAULT 'reserved' CHECK(status IN('reserved','running','completed','cancelled')),rewarded_at timestamptz);
GRANT SELECT ON public.social_participations TO authenticated; GRANT ALL ON public.social_participations TO service_role; ALTER TABLE public.social_participations ENABLE ROW LEVEL SECURITY; CREATE POLICY "own participations" ON public.social_participations FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.characters c WHERE c.id=character_id AND c.user_id=auth.uid()));
INSERT INTO public.life_rules(id,title,duration_minutes,allowed_kinds) VALUES('social','Activité sociale',45,ARRAY['universite','entreprise','cafe','parc','place','administration','mairie']);
INSERT INTO public.social_rules(id,title,relation_gain,min_score,energy_cost,cooldown_minutes,reputation_gain,influence_gain) VALUES('introduce','Se présenter',5,0,0,0,0,0),('discuss','Discuter',5,5,2,30,1,0),('know','Apprendre à connaître',8,15,3,60,1,0),('invite','Proposer une activité',0,10,0,60,0,0);
INSERT INTO public.organizations(name,kind,city_id,description,location_id)
SELECT v.prefix||' — '||c.name,v.kind,c.id,v.description,l.id FROM public.cities c CROSS JOIN (VALUES('Les Passerelles étudiantes','student','Un cercle fictif d’entraide et de rencontres étudiantes.','universite'),('Atelier des Horizons','culture','Un collectif fictif pour partager les pratiques culturelles.','cafe'),('Élan des Quartiers','sport','Un groupe fictif de sport et de sorties au parc.','parc'),('Les Voix du Quotidien','citizen','Un forum fictif de dialogue sur la vie locale, sans activité politique.','place'),('Connexions & Métiers','professional','Un réseau fictif de partage d’expériences professionnelles.','entreprise'),('Les Mains Ensemble','charity','Une association fictive d’entraide et de solidarité locale.','administration')) v(prefix,kind,description,location_kind) JOIN public.locations l ON l.city_id=c.id AND l.kind=v.location_kind AND l.district_id IS NOT NULL;
INSERT INTO public.social_npcs(first_name,last_name,age,city_id,district_id,location_id,profession,description,traits,organization_id,appearance)
SELECT v.first_name, v.last_name,c.age,l.city_id,l.district_id,l.id,v.profession,v.description,ARRAY[v.trait],o.id,jsonb_build_object('hair',v.hair,'outfit',v.outfit,'skin',v.skin) FROM (VALUES('Camille','Varenne','universite','Étudiante','Aime partager ses lectures et aider les nouveaux arrivants.','Curieuse','bun','green','s2'),('Noé','Delcourt','cafe','Illustrateur','Dessine les scènes du quartier et organise des ateliers.','Créatif','curly','coral','s3'),('Inès','Valmont','parc','Éducatrice sportive','Apprécie les activités de plein air en petit groupe.','Énergique','long','navy','s4'),('Malik','Rivière','place','Médiateur associatif','Écoute les idées et favorise les échanges entre voisins.','Attentif','short','green','s5'),('Léa','Aubrel','entreprise','Chargée de projets','Partage volontiers ses expériences professionnelles.','Méthodique','bun','charcoal','s1'),('Jules','Montclair','administration','Bénévole','Accueille les nouveaux bénévoles avec bienveillance.','Solidaire','short','sand','s2')) v(first_name,last_name,kind,profession,description,trait,hair,outfit,skin) JOIN public.locations l ON l.kind=v.kind AND l.district_id IS NOT NULL JOIN public.organizations o ON o.location_id=l.id CROSS JOIN LATERAL (SELECT CASE WHEN v.kind='universite' THEN 20 ELSE 27 END AS age) c;
INSERT INTO public.organization_events(organization_id,title,description,location_id) SELECT id,CASE kind WHEN 'student' THEN 'Rencontre d’entraide' WHEN 'culture' THEN 'Atelier créatif' WHEN 'sport' THEN 'Rencontre sportive' WHEN 'citizen' THEN 'Échanges entre voisins' WHEN 'professional' THEN 'Atelier des métiers' ELSE 'Réunion des bénévoles' END,'Un rendez-vous quotidien entre membres, à 18 h, pour agir et faire connaissance.',location_id FROM public.organizations WHERE location_id IS NOT NULL;
CREATE FUNCTION public.social_level(_score integer) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT CASE WHEN _score>=80 THEN 'Proche' WHEN _score>=50 THEN 'Ami' WHEN _score>=25 THEN 'Relation amicale' WHEN _score>=5 THEN 'Connaissance' ELSE 'Inconnu' END $$;
CREATE FUNCTION public.social_actor() RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE cid uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Non connecté'; END IF; SELECT id INTO cid FROM public.characters WHERE user_id=auth.uid() FOR UPDATE; IF cid IS NULL THEN RAISE EXCEPTION 'Personnage introuvable'; END IF; PERFORM public.settle_daily_life(cid); INSERT INTO public.social_stats(character_id) VALUES(cid) ON CONFLICT DO NOTHING; RETURN cid; END $$;
REVOKE ALL ON FUNCTION public.social_actor() FROM PUBLIC;
CREATE FUNCTION public.social_interact(_npc_id uuid,_action_id text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE cid uuid; c public.characters; n public.social_npcs; r public.social_relations; rule public.social_rules; t timestamptz:=public.game_now(); before_level text; aid uuid; start_at timestamptz; BEGIN cid:=public.social_actor(); SELECT * INTO c FROM public.characters WHERE id=cid; SELECT * INTO n FROM public.social_npcs WHERE id=_npc_id; IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM public.character_positions p JOIN public.locations l ON l.id=p.location_id WHERE p.character_id=cid AND p.city_id=n.city_id AND p.location_id=n.location_id AND l.accessible) THEN RAISE EXCEPTION 'Rejoignez le lieu de cette personne'; END IF; IF EXISTS(SELECT 1 FROM public.activities WHERE character_id=cid AND status='running') THEN RAISE EXCEPTION 'Terminez votre activité'; END IF; SELECT * INTO rule FROM public.social_rules WHERE id=_action_id; IF NOT FOUND THEN RAISE EXCEPTION 'Interaction inconnue'; END IF; SELECT * INTO r FROM public.social_relations WHERE character_id=cid AND npc_id=n.id FOR UPDATE;
IF _action_id='introduce' THEN IF r.id IS NOT NULL THEN RAISE EXCEPTION 'Vous connaissez déjà cette personne'; END IF; INSERT INTO public.social_relations(character_id,npc_id,score,met_at,last_interaction) VALUES(cid,n.id,rule.relation_gain,t,t); INSERT INTO public.notifications(user_id,title,body) VALUES(c.user_id,'Nouvelle rencontre',n.first_name||' '||n.last_name||' a rejoint vos contacts');
ELSE IF r.id IS NULL OR r.score<rule.min_score THEN RAISE EXCEPTION 'Développez d’abord votre relation'; END IF; IF r.last_interaction+rule.cooldown_minutes*interval '1 minute'>t THEN RAISE EXCEPTION 'Cette personne souhaite reprendre la discussion un peu plus tard'; END IF; IF c.energy<rule.energy_cost THEN RAISE EXCEPTION 'Énergie insuffisante'; END IF;
IF _action_id='invite' THEN start_at:=date_trunc('minute',t)+interval '1 minute'; IF EXISTS(SELECT 1 FROM public.activities WHERE character_id=cid AND status IN('planned','running') AND start_time<start_at+interval '45 minutes' AND end_time>start_at) THEN RAISE EXCEPTION 'Ce rendez-vous chevauche votre agenda'; END IF; INSERT INTO public.activities(character_id,type,title,start_time,end_time,location_id,energy_cost,social_npc_id,social_relation_gain,social_reputation_gain,social_influence_gain,source_key) VALUES(cid,'social','Rencontre avec '||n.first_name,start_at,start_at+interval '45 minutes',n.location_id,5,n.id,10,3,1,'invite:'||n.id||':'||(t AT TIME ZONE 'UTC')::date) RETURNING id INTO aid; INSERT INTO public.social_participations(activity_id,character_id,npc_id) VALUES(aid,cid,n.id); INSERT INTO public.notifications(user_id,title,body) VALUES(c.user_id,'Invitation acceptée','Votre rencontre avec '||n.first_name||' est dans l’agenda');
ELSE before_level:=public.social_level(r.score); UPDATE public.social_relations SET score=LEAST(100,score+rule.relation_gain),last_interaction=t WHERE id=r.id; IF before_level<>public.social_level(LEAST(100,r.score+rule.relation_gain)) THEN INSERT INTO public.notifications(user_id,title,body) VALUES(c.user_id,'Relation renforcée',n.first_name||' : '||public.social_level(LEAST(100,r.score+rule.relation_gain))); END IF; END IF;
UPDATE public.characters SET energy=energy-rule.energy_cost WHERE id=cid; UPDATE public.social_stats SET reputation=reputation+rule.reputation_gain,influence=influence+rule.influence_gain WHERE character_id=cid; UPDATE public.social_relations SET last_interaction=t WHERE character_id=cid AND npc_id=n.id; END IF;
INSERT INTO public.social_interactions(character_id,npc_id,action_id,relation_gain,occurred_at) VALUES(cid,n.id,rule.id,rule.relation_gain,t); END $$;
REVOKE ALL ON FUNCTION public.social_interact(uuid,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.social_interact(uuid,text) TO authenticated;
CREATE FUNCTION public.change_membership(_organization_id uuid,_join boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE cid uuid; c public.characters; o public.organizations; m public.memberships; BEGIN cid:=public.social_actor(); SELECT * INTO c FROM public.characters WHERE id=cid; SELECT * INTO o FROM public.organizations WHERE id=_organization_id AND status='active' AND visibility='public' AND location_id IS NOT NULL; IF NOT FOUND OR o.city_id<>c.city_id THEN RAISE EXCEPTION 'Organisation inaccessible depuis votre ville'; END IF; SELECT * INTO m FROM public.memberships WHERE character_id=cid AND organization_id=o.id FOR UPDATE;
IF _join THEN IF m.status='active' THEN RAISE EXCEPTION 'Vous êtes déjà membre'; END IF; IF o.kind='student' AND c.path_id<>'student' THEN RAISE EXCEPTION 'Cette association est réservée aux étudiants'; END IF; INSERT INTO public.memberships(character_id,organization_id,role,status,joined_at) VALUES(cid,o.id,'member','active',public.game_now()) ON CONFLICT(character_id,organization_id) DO UPDATE SET status='active',role='member',joined_at=EXCLUDED.joined_at,left_at=NULL; ELSE IF m.id IS NULL OR m.status<>'active' THEN RAISE EXCEPTION 'Aucune adhésion active'; END IF; IF EXISTS(SELECT 1 FROM public.activities a JOIN public.organization_events e ON e.id=a.organization_event_id WHERE a.character_id=cid AND e.organization_id=o.id AND a.status='running') THEN RAISE EXCEPTION 'Terminez l’activité avant de quitter'; END IF; UPDATE public.memberships SET status='former',left_at=public.game_now() WHERE id=m.id; UPDATE public.activities a SET status='cancelled' FROM public.organization_events e WHERE a.organization_event_id=e.id AND e.organization_id=o.id AND a.character_id=cid AND a.status='planned'; END IF;
INSERT INTO public.membership_history(character_id,organization_id,action,occurred_at) VALUES(cid,o.id,CASE WHEN _join THEN 'joined' ELSE 'left' END,public.game_now()); INSERT INTO public.notifications(user_id,title,body) VALUES(c.user_id,CASE WHEN _join THEN 'Adhésion confirmée' ELSE 'Organisation quittée' END,o.name); END $$;
REVOKE ALL ON FUNCTION public.change_membership(uuid,boolean) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.change_membership(uuid,boolean) TO authenticated;
CREATE FUNCTION public.reserve_social_event(_event_id uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE cid uuid; c public.characters; e public.organization_events; o public.organizations; start_at timestamptz; aid uuid; t timestamptz:=public.game_now(); BEGIN cid:=public.social_actor(); SELECT * INTO c FROM public.characters WHERE id=cid; SELECT * INTO e FROM public.organization_events WHERE id=_event_id AND status='active'; IF NOT FOUND THEN RAISE EXCEPTION 'Activité introuvable'; END IF; SELECT * INTO o FROM public.organizations WHERE id=e.organization_id; IF o.city_id<>c.city_id OR o.status<>'active' OR NOT EXISTS(SELECT 1 FROM public.memberships WHERE character_id=cid AND organization_id=o.id AND status='active') THEN RAISE EXCEPTION 'Rejoignez cette organisation pour participer'; END IF; IF NOT EXISTS(SELECT 1 FROM public.locations l JOIN public.districts d ON d.id=l.district_id WHERE l.id=e.location_id AND l.city_id=c.city_id AND l.accessible AND d.available) THEN RAISE EXCEPTION 'Lieu inaccessible'; END IF; start_at:=((t AT TIME ZONE 'UTC')::date+make_time(e.start_hour,0,0)) AT TIME ZONE 'UTC'; IF start_at<t THEN start_at:=start_at+interval '1 day'; END IF; IF EXISTS(SELECT 1 FROM public.activities WHERE character_id=cid AND status IN('planned','running') AND start_time<start_at+e.duration_minutes*interval '1 minute' AND end_time>start_at) THEN RAISE EXCEPTION 'Cette activité chevauche votre agenda'; END IF;
INSERT INTO public.activities(character_id,type,title,start_time,end_time,location_id,energy_cost,organization_event_id,social_relation_gain,social_reputation_gain,social_influence_gain,source_key) VALUES(cid,'social',e.title,start_at,start_at+e.duration_minutes*interval '1 minute',e.location_id,e.energy_cost,e.id,e.relation_gain,e.reputation_gain,e.influence_gain,'org:'||e.id||':'||(start_at AT TIME ZONE 'UTC')::date) RETURNING id INTO aid; INSERT INTO public.social_participations(activity_id,character_id,event_id) VALUES(aid,cid,e.id); INSERT INTO public.notifications(user_id,title,body) VALUES(c.user_id,'Prochaine activité sociale',e.title||' — votre participation est dans l’agenda'); RETURN aid; END $$;
REVOKE ALL ON FUNCTION public.reserve_social_event(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.reserve_social_event(uuid) TO authenticated;
CREATE FUNCTION public.guard_social_activity() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.type='social' AND NEW.status='running' AND OLD.status IS DISTINCT FROM 'running' THEN IF NOT EXISTS(SELECT 1 FROM public.social_participations WHERE activity_id=NEW.id AND character_id=NEW.character_id) THEN RAISE EXCEPTION 'Réservez cette activité sociale'; END IF; IF NEW.organization_event_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.organization_events e JOIN public.memberships m ON m.organization_id=e.organization_id WHERE e.id=NEW.organization_event_id AND m.character_id=NEW.character_id AND m.status='active') THEN RAISE EXCEPTION 'Adhésion active requise'; END IF; IF NEW.social_npc_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.social_npcs WHERE id=NEW.social_npc_id AND location_id=NEW.location_id) THEN RAISE EXCEPTION 'Rencontre inaccessible'; END IF; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.guard_social_activity() FROM PUBLIC; CREATE TRIGGER guard_social_activity BEFORE INSERT OR UPDATE ON public.activities FOR EACH ROW EXECUTE FUNCTION public.guard_social_activity();
CREATE FUNCTION public.settle_social_activity() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.characters; n public.social_npcs; rel public.social_relations; org uuid; BEGIN IF NEW.type<>'social' OR NEW.status IS NOT DISTINCT FROM OLD.status THEN RETURN NEW; END IF; UPDATE public.social_participations SET status=CASE NEW.status WHEN 'planned' THEN 'reserved' ELSE NEW.status END WHERE activity_id=NEW.id; IF NEW.status<>'completed' THEN RETURN NEW; END IF; IF NEW.end_time>public.game_now() OR OLD.status<>'running' THEN RAISE EXCEPTION 'Cette activité n’est pas terminée'; END IF; UPDATE public.social_participations SET rewarded_at=public.game_now() WHERE activity_id=NEW.id AND rewarded_at IS NULL; IF NOT FOUND THEN RETURN NEW; END IF; SELECT * INTO c FROM public.characters WHERE id=NEW.character_id; INSERT INTO public.social_stats(character_id,reputation,influence) VALUES(c.id,NEW.social_reputation_gain,NEW.social_influence_gain) ON CONFLICT(character_id) DO UPDATE SET reputation=social_stats.reputation+EXCLUDED.reputation,influence=social_stats.influence+EXCLUDED.influence;
IF NEW.organization_event_id IS NOT NULL THEN SELECT organization_id INTO org FROM public.organization_events WHERE id=NEW.organization_event_id; UPDATE public.memberships SET progress=progress+1 WHERE character_id=c.id AND organization_id=org AND status='active'; END IF;
FOR n IN SELECT * FROM public.social_npcs WHERE id=NEW.social_npc_id OR (org IS NOT NULL AND organization_id=org AND location_id=NEW.location_id) LOOP SELECT * INTO rel FROM public.social_relations WHERE character_id=c.id AND npc_id=n.id; INSERT INTO public.social_relations(character_id,npc_id,score,met_at,last_interaction) VALUES(c.id,n.id,LEAST(100,NEW.social_relation_gain),public.game_now(),public.game_now()) ON CONFLICT(character_id,npc_id) DO UPDATE SET score=LEAST(100,social_relations.score+EXCLUDED.score),last_interaction=EXCLUDED.last_interaction; IF rel.id IS NULL THEN INSERT INTO public.notifications(user_id,title,body) VALUES(c.user_id,'Nouvelle rencontre',n.first_name||' a rejoint vos contacts lors de l’activité'); ELSIF public.social_level(rel.score)<>public.social_level(LEAST(100,rel.score+NEW.social_relation_gain)) THEN INSERT INTO public.notifications(user_id,title,body) VALUES(c.user_id,'Relation renforcée',n.first_name||' : '||public.social_level(LEAST(100,rel.score+NEW.social_relation_gain))); END IF; END LOOP;
INSERT INTO public.notifications(user_id,title,body) VALUES(c.user_id,'Activité sociale terminée',NEW.title||' : +'||NEW.social_reputation_gain||' réputation, +'||NEW.social_influence_gain||' influence'); RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.settle_social_activity() FROM PUBLIC; CREATE TRIGGER settle_social_activity AFTER UPDATE ON public.activities FOR EACH ROW EXECUTE FUNCTION public.settle_social_activity();
CREATE FUNCTION public.social_state() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE cid uuid; BEGIN cid:=public.social_actor(); RETURN jsonb_build_object('world_now',public.game_now(),'stats',(SELECT to_jsonb(s) FROM public.social_stats s WHERE character_id=cid),'relations',COALESCE((SELECT jsonb_agg(to_jsonb(r)||jsonb_build_object('level',public.social_level(r.score),'npc',to_jsonb(n)||jsonb_build_object('location',to_jsonb(l))) ORDER BY r.score DESC) FROM public.social_relations r JOIN public.social_npcs n ON n.id=r.npc_id JOIN public.locations l ON l.id=n.location_id WHERE r.character_id=cid),'[]'::jsonb),'nearby',COALESCE((SELECT jsonb_agg(to_jsonb(n)||jsonb_build_object('location',to_jsonb(l))) FROM public.social_npcs n JOIN public.locations l ON l.id=n.location_id JOIN public.character_positions p ON p.location_id=n.location_id WHERE p.character_id=cid),'[]'::jsonb),'memberships',COALESCE((SELECT jsonb_agg(m) FROM public.memberships m WHERE character_id=cid),'[]'::jsonb),'history',COALESCE((SELECT jsonb_agg(i ORDER BY occurred_at DESC) FROM (SELECT * FROM public.social_interactions WHERE character_id=cid ORDER BY occurred_at DESC LIMIT 30) i),'[]'::jsonb),'rules',(SELECT jsonb_agg(r) FROM public.social_rules r),'participations',COALESCE((SELECT jsonb_agg(p) FROM public.social_participations p WHERE character_id=cid),'[]'::jsonb)); END $$;
REVOKE ALL ON FUNCTION public.social_state() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.social_state() TO authenticated;
CREATE FUNCTION public.organization_directory(_city_id text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Non connecté'; END IF; RETURN COALESCE((SELECT jsonb_agg(to_jsonb(o)||jsonb_build_object('location',to_jsonb(l),'city_name',ci.name,'member_count',(SELECT count(*) FROM public.memberships m WHERE m.organization_id=o.id AND m.status='active')+(SELECT count(*) FROM public.social_npcs n WHERE n.organization_id=o.id),'members',COALESCE((SELECT jsonb_agg(jsonb_build_object('first_name',n.first_name,'last_name',n.last_name,'role','member','fictional',true)) FROM public.social_npcs n WHERE n.organization_id=o.id),'[]'::jsonb)||COALESCE((SELECT jsonb_agg(jsonb_build_object('first_name',c.first_name,'last_name',c.last_name,'role',m.role,'fictional',false)) FROM public.memberships m JOIN public.characters c ON c.id=m.character_id WHERE m.organization_id=o.id AND m.status='active' AND c.user_id=auth.uid()),'[]'::jsonb),'events',COALESCE((SELECT jsonb_agg(to_jsonb(e)||jsonb_build_object('participant_count',(SELECT count(*) FROM public.activities a WHERE a.organization_event_id=e.id AND a.status IN('planned','running') AND a.start_time>=public.game_now()))) FROM public.organization_events e WHERE e.organization_id=o.id AND e.status='active'),'[]'::jsonb)) ORDER BY o.kind,o.name) FROM public.organizations o JOIN public.locations l ON l.id=o.location_id JOIN public.cities ci ON ci.id=o.city_id WHERE o.city_id=_city_id AND o.status='active' AND o.visibility='public'),'[]'::jsonb); END $$;
REVOKE ALL ON FUNCTION public.organization_directory(text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.organization_directory(text) TO authenticated;
COMMENT ON FUNCTION public.social_actor() IS 'Locks the caller character before every social operation; existing clock and settlement remain authoritative.';
COMMENT ON TABLE public.social_npcs IS 'Fictional public game identities only; never contains real players or auth data.';
COMMENT ON TABLE public.membership_history IS 'Reactivation keeps one membership identity while preserving entry and departure history.';